command:
if ([...game.combats].filter(combat => combat.isActive).length === 0) {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: darkgreen;">${game.i18n.format("FQCARDENGINE.MacroMsgCatchingBreath")}</h3>`
    });
    game.user.character.update({ "system.fq.action.value": game.user.character.system.fq.action.max});
    foundry.audio.AudioHelper.play({
        src: "modules/fq-card-engine/sounds/passive_spells/breathe.mp3",
        volume: 0.5,
        autoplay: true,
        loop: false
    }, true);
} else {
    ChatMessage.create({
        speaker: {user: game.user.character},
        content: `<h3 style="color: #C0392B;">${game.i18n.format("FQCARDENGINE.WarningMsgSpellUseOutCombat")}</h3>`
    });
}
